using System;
using System.IO;
using System.Linq;
using System.Text;
using CapriDesktop;

internal static class NativeEditorChecks
{
    internal static void Run()
    {
        int count=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
        string folder=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"capri-editor-checks-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
        NativeEditorDocument Document(string path,string head="default\n")=>new(System.IO.Path.GetFileName(path),()=>new WrittenNote(path,head,new object()));
        try
        {
            string missing=System.IO.Path.Combine(folder,"missing","me.md");var fresh=Document(missing);fresh.Read();Check(!File.Exists(missing)&&!Directory.Exists(System.IO.Path.GetDirectoryName(missing)),"opening a missing note does not create a file or folder");Check(fresh.Draft=="default\n"&&!fresh.Dirty,"missing note displays its virtual default without dirtying it");
            fresh.Edit("é 北 👩🏽‍💻\nnew\n");Check(fresh.Dirty,"Unicode edits are dirty");Check(fresh.Save()==null&&File.ReadAllText(missing)=="é 北 👩🏽‍💻\nnew\n","explicit save atomically creates the Unicode note");Check(!fresh.Dirty,"successful save updates the captured baseline");
            if(!OperatingSystem.IsWindows())Check(File.GetUnixFileMode(missing)==(UnixFileMode.UserRead|UnixFileMode.UserWrite),"new native note is private0600");
            string a=System.IO.Path.Combine(folder,"personality.md"),b=System.IO.Path.Combine(folder,"me.md");File.WriteAllText(a,"first\r\nsecond\r\n");File.WriteAllText(b,"B\n");File.SetLastWriteTimeUtc(a,new DateTime(2001,1,1,0,0,0,DateTimeKind.Utc));var ad=Document(a);var bd=Document(b);ad.Read();bd.Read();Check(File.GetLastWriteTimeUtc(a).Year==2001&&File.ReadAllText(a)=="first\r\nsecond\r\n","opening an existing note preserves timestamp and bytes");
            ad.Edit("A λ\nedit\n");bd.Edit("B draft\n");Check(ad.Draft=="A λ\nedit\n"&&bd.Draft=="B draft\n"&&ad.Dirty&&bd.Dirty,"tabs retain independent dirty drafts");
            Check(ad.Save()==null&&File.ReadAllText(a)=="A λ\r\nedit\r\n","CRLF note keeps its newline convention after editing");Check(bd.Dirty&&bd.Draft=="B draft\n","saving one tab does not clear another draft");
            bd.Read();Check(bd.Draft=="B draft\n","background recheck preserves dirty draft");File.WriteAllText(b,"external\n");string problem=bd.Save();Check(problem!=null&&problem.Contains("changed")&&File.ReadAllText(b)=="external\n","external writer cannot be overwritten by stale save");Check(bd.Dirty&&bd.Draft=="B draft\n","conflict keeps unsaved text");Check(bd.Reload()&&bd.Draft=="external\n"&&!bd.Dirty,"explicit reload adopts disk and clears the old draft");
            File.WriteAllText(b,"another writer\n");bd.Read();Check(bd.Draft=="another writer\n","clean tab refreshes external changes");bd.Edit("discard me");bd.Discard();Check(!bd.Dirty&&bd.Draft=="another writer\n","discard returns only that tab to its snapshot");
            string cr=System.IO.Path.Combine(folder,"cr.md");File.WriteAllText(cr,"one\rtwo\r");var cd=Document(cr);cd.Read();cd.Edit("one\nthree\n");Check(cd.Save()==null&&File.ReadAllText(cr)=="one\rthree\r","CR-only files preserve their newline convention");
            string mixed=System.IO.Path.Combine(folder,"mixed.md");File.WriteAllText(mixed,"one\r\ntwo\nthree\r");var md=Document(mixed);md.Read();Check(md.ForFile()=="one\r\ntwo\nthree\r","unchanged mixed newlines remain byte-for-text identical");
            string recovery=System.IO.Path.Combine(folder,"recovery.md");File.WriteAllText(recovery,"base\n");var rd=Document(recovery);rd.Read();rd.Edit("recover α\n");Check(rd.KeepDraft()==null&&File.ReadAllText(recovery)=="base\n","shutdown recovery keeps the draft without altering the note");Check(File.Exists(recovery+".unsaved")&&File.Exists(recovery+".unsaved.meta"),"recovery text and base identity are retained");
            if(!OperatingSystem.IsWindows())Check(File.GetUnixFileMode(recovery+".unsaved")== (UnixFileMode.UserRead|UnixFileMode.UserWrite)&&File.GetUnixFileMode(recovery+".unsaved.meta")== (UnixFileMode.UserRead|UnixFileMode.UserWrite),"recovery data is private0600");
            var restored=Document(recovery);restored.Read();Check(restored.Draft=="recover α\n"&&restored.Dirty&&!restored.RecoveryConflict,"matching recovery returns as unsaved text");Check(File.Exists(recovery+".unsaved"),"opening recovery does not rewrite or delete its sidecar");Check(restored.Save()==null&&File.ReadAllText(recovery)=="recover α\n"&&!File.Exists(recovery+".unsaved")&&!File.Exists(recovery+".unsaved.meta"),"explicit save commits recovery and removes its sidecars");
            restored.Edit("old unsaved\n");restored.KeepDraft();File.WriteAllText(recovery,"external after shutdown\n");var conflict=Document(recovery);conflict.Read();Check(conflict.RecoveryConflict&&conflict.Draft=="old unsaved\n","recovery detects a changed disk baseline");Check(conflict.Save()!=null&&File.ReadAllText(recovery)=="external after shutdown\n","stale recovered draft cannot overwrite newer disk text");conflict.Edit("modified stale draft\n");conflict.KeepDraft();var stillConflict=Document(recovery);stillConflict.Read();Check(stillConflict.RecoveryConflict,"a repeated shutdown cannot bless an unreviewed recovery baseline");
            string legacy=System.IO.Path.Combine(folder,"legacy.md");File.WriteAllText(legacy,"disk\n");File.WriteAllText(legacy+".unsaved","old draft\n");var ld=Document(legacy);ld.Read();Check(ld.RecoveryConflict&&ld.Save()!=null&&ld.Draft=="old draft\n","legacy recovery without base identity is retained but cannot silently overwrite disk");
            string interrupted=System.IO.Path.Combine(folder,"interrupted.md");File.WriteAllText(interrupted,"base\n");var ir=Document(interrupted);ir.Read();ir.Edit("first draft\n");ir.KeepDraft();File.WriteAllText(interrupted+".unsaved","second draft interrupted\n");var afterPartial=Document(interrupted);afterPartial.Read();Check(afterPartial.RecoveryConflict&&afterPartial.Save()!=null&&afterPartial.Draft=="second draft interrupted\n","interrupted draft/metadata replacement cannot silently approve a new baseline");File.WriteAllText(interrupted+".unsaved.meta","not JSON");var corrupt=Document(interrupted);corrupt.Read();Check(corrupt.RecoveryConflict&&corrupt.Draft=="second draft interrupted\n"&&corrupt.Save()!=null,"corrupt recovery metadata retains text and blocks stale save");
            var absentNote=new WrittenNote(System.IO.Path.Combine(folder,"exists.md"),"head",new object());Check(!absentNote.Existed&&absentNote.Save("saved")==null&&absentNote.Existed,"shared note existence reflects its authoritative read/save snapshot");
            string bad=System.IO.Path.Combine(folder,"blocked");File.WriteAllText(bad,"not a folder");var fail=Document(System.IO.Path.Combine(bad,"me.md"));fail.Read();fail.Edit("keep this");Check(fail.Save()!=null&&fail.Draft=="keep this"&&fail.Dirty,"failed save preserves the entire draft");Check(fail.KeepDraft()!=null&&fail.Draft=="keep this","failed recovery save is reported without losing memory");
            int reads=0;var readFail=new NativeEditorDocument("failed.md",()=>{if(reads++==0)throw new IOException("fixture read failure");return new WrittenNote(System.IO.Path.Combine(folder,"retry.md"),"retry\n",new object());});readFail.Read();Check(readFail.ReadOnly&&readFail.Problem!=null,"read failure stays actionable and cannot write an unknown file baseline");readFail.Read();Check(!readFail.ReadOnly&&readFail.Draft=="retry\n","a later successful read recovers the editor tab");
            foreach(var encoding in new Encoding[]{new UTF8Encoding(true),new UnicodeEncoding(false,true),new UnicodeEncoding(true,true),new UTF32Encoding(false,true),new UTF32Encoding(true,true)})
            {
                string path=System.IO.Path.Combine(folder,"bom-"+encoding.CodePage+".md");File.WriteAllText(path,"BOM α\r\n",encoding);var doc=Document(path);doc.Read();doc.Edit("BOM 北\nchanged\n");Check(doc.Save()==null&&File.ReadAllBytes(path).Take(encoding.GetPreamble().Length).SequenceEqual(encoding.GetPreamble())&&File.ReadAllText(path)=="BOM 北\r\nchanged\r\n","native save preserves BOM encoding "+encoding.CodePage);
            }
            if(!OperatingSystem.IsWindows()){File.SetUnixFileMode(a,UnixFileMode.UserRead|UnixFileMode.UserWrite);ad.Read();ad.Edit("private\n");Check(ad.Save()==null&&File.GetUnixFileMode(a)==(UnixFileMode.UserRead|UnixFileMode.UserWrite),"atomic replace cannot widen an existing0600note");}
            Check(!Directory.EnumerateFiles(folder,"*.new",SearchOption.AllDirectories).Any(),"successful and failed saves leave no temporary file");
            var one=new NativeEditorMotion();one.Advance(1.25);var many=new NativeEditorMotion();for(int i=0;i<125;i++)many.Advance(.01);Check(Math.Abs(one.Frame-many.Frame)<1e-8,"opening follows elapsed time independent of timer cadence");one.Advance(2);Check(one.Stage==NativeEditorMotion.Phase.Open&&one.Frame==59,"opening settles at authored final frame59");one.Close();one.Advance(14.0/24);Check(one.Stage==NativeEditorMotion.Phase.Closing&&Math.Abs(one.Frame-40)<1e-8,"closing untypes then reverses the settled geometry");one.Advance(.5);Check(one.Frame<40&&one.Frame>0,"closing geometry rewinds");one.Open();one.Advance(3);Check(one.Stage==NativeEditorMotion.Phase.Open,"reopening interrupts reverse close and returns forwards");one.Close();one.Advance(10);Check(one.Stage==NativeEditorMotion.Phase.Gone&&one.Frame==0,"close completes without a leftover surface");
            var sheet=NativeEditorArt.Sheet(59);Check(sheet.Length==7&&sheet[0].X==172&&sheet[0].Y==164&&sheet[5].X==636.5&&sheet[5].Y==552.5,"sheet preserves released coordinates and stepped foot");Check(Math.Abs(NativeEditorArt.Glassy(59)-.78)<1e-9,"settled glass preserves original alpha");Check(NativeEditorArt.Page(1.6).Width>640&&NativeEditorArt.Page(1.6).Height>590,"default art page has real editing room");
            Console.WriteLine("PASS native editor state/art/motion checks="+count);
        }
        finally { Directory.Delete(folder,true); }
    }
}
